return System.IO.Directory.GetFiles("Assets/EchoStation/InfiltrationRefinement/ThirdParty","*.fbx").Select(p=>new{path=p,materials=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p.Replace('\\','/')).GetComponentsInChildren<UnityEngine.Renderer>().SelectMany(r=>r.sharedMaterials).Select(m=>new{name=m.name,shader=m.shader.name,texture=UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap"))}).ToArray()}).ToArray();
